import{_ as t,o as e,c as r,ae as o}from"./chunks/framework.DQC_QtFV.js";const c=JSON.parse('{"title":"免责声明","description":"","frontmatter":{},"headers":[],"relativePath":"guide/disclaimer.md","filePath":"guide/disclaimer.md","lastUpdated":1793162416000}'),i={name:"guide/disclaimer.md"};function l(n,a,s,d,u,h){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="免责声明" tabindex="-1">免责声明 <a class="header-anchor" href="#免责声明" aria-label="Permalink to &quot;免责声明&quot;">​</a></h1><p>完整文本在仓库的 <a href="https://github.com/4fuu/personal-bot/blob/main/DISCLAIMER.md" target="_blank" rel="noreferrer">DISCLAIMER.md</a>， 这一页是它的要点。运行任何东西之前请读全文。</p><h2 id="与腾讯无关" tabindex="-1">与腾讯无关 <a class="header-anchor" href="#与腾讯无关" aria-label="Permalink to &quot;与腾讯无关&quot;">​</a></h2><p>personal-bot 是一个独立的第三方互操作项目，<strong>与腾讯、与 QQ 没有任何隶属、合作、 授权或背书关系</strong>，也不是腾讯的官方产品。&quot;QQ&quot;、&quot;腾讯&quot; 及相关商标归其各自的所有者。 这里没有任何东西由腾讯提供、审查或认可。</p><h2 id="它做什么-说清楚" tabindex="-1">它做什么，说清楚 <a class="header-anchor" href="#它做什么-说清楚" aria-label="Permalink to &quot;它做什么，说清楚&quot;">​</a></h2><p>整套栈在容器里、在虚拟显示上运行<strong>官方的、未修改的 Linux 版 QQ NT 桌面客户端</strong>， 只对这个客户端做三件事：</p><ul><li>从客户端自己本地数据库的<strong>一份私有解密副本</strong>里读消息，这份副本不离开你的机器；</li><li>通过一个启动时预加载进客户端的小型库，调用客户端<strong>自己的发送函数</strong>发消息—— 客户端自身的文件不被补丁、不被替换、也不被写入；</li><li>客户端回到账号页时，通过无障碍总线点它自己的 登录 按钮，让保存的会话自己恢复。 扫码登录保持手动，由你完成。</li></ul><p>它不读别的东西：不读你的联系人（除了客户端自己显示的名字）， 不听客户端的事件流，除了你配置的模型服务商和你连接的 MCP 服务端，什么都不往外发。</p><h2 id="风险由你承担" tabindex="-1">风险由你承担 <a class="header-anchor" href="#风险由你承担" aria-label="Permalink to &quot;风险由你承担&quot;">​</a></h2><p>自动化一个聊天客户端不在该客户端的服务条款允许范围内。你用来运行它的账号 <strong>可能被限制、暂停或永久封禁</strong>，本地消息历史也可能随之丢失。这个风险是你的， 你是自愿承担的。</p><p>把它压到最小的方法：</p><ul><li>用一个小号，一个已经有一些历史记录的小号，不要用新号；</li><li>用家庭宽带，不要用数据中心 IP；</li><li>保留默认的发送节奏，不要调高；</li><li>保留客户端自己的版本，不要让它自己更新。</li></ul><h2 id="按-现状-提供" tabindex="-1">按&quot;现状&quot;提供 <a class="header-anchor" href="#按-现状-提供" aria-label="Permalink to &quot;按&quot;现状&quot;提供&quot;">​</a></h2><p>本项目<strong>按现状</strong>、<strong>按可用</strong>提供，不提供任何明示或暗示的担保， 包括适销性、特定用途适用性、不侵权、可用性、准确性和不中断运行。 在法律允许的最大范围内，作者和版权持有人对任何直接、间接、附带、特殊、惩罚性 或后果性损害——包括账号被限制或丢失、数据丢失、利润或业务损失、服务中断—— 不承担责任，无论它们是由使用还是无法使用本项目引起的。</p><h2 id="不用于违法用途" tabindex="-1">不用于违法用途 <a class="header-anchor" href="#不用于违法用途" aria-label="Permalink to &quot;不用于违法用途&quot;">​</a></h2><p>你不得将本项目用于任何违法目的，包括垃圾信息、骚扰、欺诈、未授权访问任何系统或网络、 或传播恶意内容。你有责任确保你的使用符合适用于你的法律以及你连接的每一个平台的条款。</p>',16)])])}const m=t(i,[["render",l]]);export{c as __pageData,m as default};
